import{_ as o,o as t,c as a,ag as s}from"./chunks/framework.D9kpkP22.js";const h=JSON.parse('{"title":"Frost — Commands & Permissions","description":"","frontmatter":{"title":"Frost — Commands & Permissions"},"headers":[],"relativePath":"frost/commands.md","filePath":"frost/commands.md"}'),i={name:"frost/commands.md"};function r(l,e,d,n,c,m){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="commands-permissions" tabindex="-1">Commands &amp; Permissions <a class="header-anchor" href="#commands-permissions" aria-label="Permalink to &quot;Commands &amp; Permissions&quot;">​</a></h1><h2 id="player-commands" tabindex="-1">Player Commands <a class="header-anchor" href="#player-commands" aria-label="Permalink to &quot;Player Commands&quot;">​</a></h2><h3 id="shop" tabindex="-1">/shop <a class="header-anchor" href="#shop" aria-label="Permalink to &quot;/shop&quot;">​</a></h3><ul><li>Opens the cosmetics shop GUI.</li><li>Permission: <code>frost.shop</code> (default: true)</li></ul><h3 id="equip" tabindex="-1">/equip <a class="header-anchor" href="#equip" aria-label="Permalink to &quot;/equip&quot;">​</a></h3><ul><li>Opens your equip menu to toggle owned cosmetics.</li><li>Permission: <code>frost.equip</code> (default: true)</li></ul><h3 id="togglelock" tabindex="-1">/togglelock <a class="header-anchor" href="#togglelock" aria-label="Permalink to &quot;/togglelock&quot;">​</a></h3><ul><li>Toggles Hotbar Lock on/off and refreshes locked items when enabling.</li><li>Permission: none (player self‑service)</li></ul><h2 id="admin-command" tabindex="-1">Admin Command <a class="header-anchor" href="#admin-command" aria-label="Permalink to &quot;Admin Command&quot;">​</a></h2><h3 id="frost-reload" tabindex="-1">/frost reload <a class="header-anchor" href="#frost-reload" aria-label="Permalink to &quot;/frost reload&quot;">​</a></h3><ul><li>Reloads <code>config.yml</code>, profiles, and cosmetics from disk.</li><li>Permission: <code>frost.admin</code></li></ul><h3 id="frost-setprofile-player-profile" tabindex="-1"><code>/frost setprofile &lt;player&gt; &lt;profile&gt;</code> <a class="header-anchor" href="#frost-setprofile-player-profile" aria-label="Permalink to &quot;`/frost setprofile &lt;player&gt; &lt;profile&gt;`&quot;">​</a></h3><ul><li>Sets a player’s active profile (must exist under <code>profiles</code> in <code>config.yml</code>).</li><li>Permission: <code>frost.admin</code></li></ul><h3 id="frost-listprofiles" tabindex="-1">/frost listprofiles <a class="header-anchor" href="#frost-listprofiles" aria-label="Permalink to &quot;/frost listprofiles&quot;">​</a></h3><ul><li>Lists all available profile IDs and display names.</li><li>Permission: <code>frost.admin</code></li></ul><h3 id="frost-givecosmetic-player-cosmetic" tabindex="-1"><code>/frost givecosmetic &lt;player&gt; &lt;cosmetic&gt;</code> <a class="header-anchor" href="#frost-givecosmetic-player-cosmetic" aria-label="Permalink to &quot;`/frost givecosmetic &lt;player&gt; &lt;cosmetic&gt;`&quot;">​</a></h3><ul><li>Grants a cosmetic directly (bypasses economy) and saves it to the player’s data.</li><li>Permission: <code>frost.admin</code></li></ul><h2 id="permissions-reference" tabindex="-1">Permissions Reference <a class="header-anchor" href="#permissions-reference" aria-label="Permalink to &quot;Permissions Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>frost.admin</code></td><td>Access to admin commands</td><td>op</td></tr><tr><td><code>frost.shop</code></td><td>Open the cosmetics shop</td><td>true</td></tr><tr><td><code>frost.equip</code></td><td>Open the equip menu</td><td>true</td></tr><tr><td><code>frost.profile.&lt;profile-name&gt;</code></td><td>Gate access to specific profiles (optional)</td><td>—</td></tr></tbody></table>',19)])])}const p=o(i,[["render",r]]);export{h as __pageData,p as default};
